def _step(x, y, one):
    """One Euclid step preserving ``gcd(x, y)``; lanes with ``x == 0`` are
    frozen with the answer held in ``y``.

    The remainder is taken as ``y % x`` rather than ``x % y`` so that data whose
    gcd has already been taken (``x`` divides ``y``) finishes after one step.
    """
    xs = tl.where(x == 0, one, x)
    r = tl.where(x == 0, x, y % xs)
    return r, tl.where(x == 0, y, x)


