def _wrap_mag(ai, ELEM_BITS: tl.constexpr, MINVAL: tl.constexpr):
    """Wrapped two's-complement magnitude of a signed operand.

    The negation wraps inside the operand width, so the dtype minimum keeps its
    negative bit pattern exactly like the reference implementation.
    """
    m = tl.where(ai < 0, -ai, ai)
    if ELEM_BITS < 32:
        m = tl.where(ai == MINVAL, ai, m)
    return m


